<script>
   /******************************************************************/
   /* DownloadsComponent                                             */
   /* -------------------------                                      */
   /* lets user download main outcomes                               */
   /******************************************************************/

   import { Container, Button } from 'svelte-controls-basic';
   import { downloadResults, downloadModel } from '@mdatools-apps/shared/methods/simca.js';
   import { downloadData, downloadCSV, excludeVars, isempty } from '@mdatools-apps/shared/utils';
   import { progressCSV } from './utils';


   let {s} = $props()


   /*****************************************/
   /* Component code                        */
   /*****************************************/

   /**
    * Let user to download the current results
    * @param name
    * @param currentRes
    */
   function downloadLOVEData(dataset, varsExcluded) {

      if (!varsExcluded || varsExcluded.length === 0) {
         downloadData(dataset, `${dataset.fileName}`);
         return;
      }
      downloadData(excludeVars(dataset, varsExcluded), `${dataset.fileName}-reduced`);
   }

   /**
    * Let user to download the current results
    * @param name
    * @param currentRes
    */
   function downloadLOVEResults(name, dataset, currentOutcomes) {
      const model = currentOutcomes.model;
      const simca = currentOutcomes.simca;
      const res = currentOutcomes[name];
      downloadResults(model, simca, res, dataset, name, 'ddsimca-love');
   }

   /**
    * Let user to download the current results
    * @param name
    * @param currentRes
    */
   function downloadLOVEModel(currentRes) {
      // the fitted model carries the preprocessing it was fitted after
      downloadModel(currentRes.model, currentRes.simca, currentRes.model.prep, 'ddsimca-love');
   }
</script>

{#if s.varsExcluded && s.varsExcluded.length > 0}

<!-- 'Full progress' reads 'statsProgress'; the Model button below and the two in 'Results'
     read 'currentRes'. nothing else in this panel reads either, so those four are gated and
     the panel is not; this container is gated on one of the two so that it is not rendered
     empty. a restored session can carry the exclusion lists beside an absent progress list:
     the session check keeps them and raises the reset refusal, under which this panel is
     rendered. 'currentRes' holds no result before the first exclusion - 'initSession'
     declares it as 0 - nor while an exclusion or an undo is recomputing, nor after one of
     those fails or is reset. a LOVE selection run does not clear it -->
{#if s.statsProgress || s.currentRes}
<Container label='Outcomes'>
   <span class="buttons">
   {#if s.statsProgress}
   <Button text="Full progress" onclick={() => downloadCSV(
      progressCSV(s.statsProgress, s.calset.sep, s.calset.dec), 'ddsimca-love-progress')} />
   {/if}
   {#if s.currentRes}
   <Button onclick={() => downloadLOVEModel(s.currentRes)} text="Model" />
   {/if}
   </span>
</Container>
{/if}
{#if s.currentRes}
<Container label='Results'>
   <span class="buttons">
   <Button onclick={() => downloadLOVEResults("tar", s.tarsetp, s.currentRes)} text="Target" />
   {#if !isempty(s.altset)}
   <Button onclick={() => downloadLOVEResults("alt", s.altsetp, s.currentRes)} text="Alt" />
   {/if}
   </span>
</Container>
{/if}
<Container label='Reduced data'>
   <span class="buttons">
   <Button onclick={() => downloadLOVEData(s.calsetp, s.varsExcluded)} text="Train" />
   <Button onclick={() => downloadLOVEData(s.tarsetp, s.varsExcluded)} text="Target" />
   {#if !isempty(s.altset)}
   <Button onclick={() => downloadLOVEData(s.altsetp, s.varsExcluded)} text="Alt" />
   {/if}
   </span>
</Container>
{/if}

<style>
   .buttons {
      position: relative;
      box-sizing: border-box;
      display: inline-block;
      flex: 1 1 auto;
      margin: 0;
      padding: 2px 0;
      width: auto;
      border-radius: 2px;
      cursor: default;
      white-space: nowrap;
   }
</style>