import { vector } from 'mdatools/arrays';
import { mean, variance, sd } from 'mdatools/stat';
import { pnorm, qchisq } from 'mdatools/distributions';

import { pca_predict, pca_fit, pcares_get, pcamodel_get } from '@mdatools-apps/wasm/pca.js';
import { predict } from '@mdatools-apps/shared/methods/simca.js';
import { applyPrep } from '@mdatools-apps/shared/methods/prep.js';
import { genhash, isempty, seq, checkedRowNumbers, csvRow, withoutExcluded, withoutResiduals }
   from '@mdatools-apps/shared/utils';



/**
 * Builds the preprocessed twin of a raw test set.
 *
 * The loader gave the raw set the model's labels and values, which a trim step has already cut,
 * so they are taken from the training twin AFTER 'applyPrep' - 'prep_trim' would cut them again.
 *
 * @param {Object} Module - the WASM module.
 * @param {Object} d - the raw set; a plain object, as 'cloneFullData' clones it with
 * structuredClone, which refuses a proxy.
 * @param {Object} prepmodel - the fitted preprocessing model.
 * @param {Object} cal - holds the training twin's 'varlabels', 'varvalues' and 'varindices'.
 */
export function buildTwin(Module, d, prepmodel, cal) {
   const t = applyPrep(Module, d, prepmodel);
   t.varlabels = cal.varlabels;
   t.varvalues = cal.varvalues;
   t.varindices = cal.varindices;
   return t;
}


/**
 * Creates object with SIMCA results objects which have the same structure as the main DD-SIMCA app.
 * This is required to download the results.
 *
 * @param {Function} WASM - the module factory.
 * @param {Object} s - current state
 */
export async function getCurrentRes(WASM, s) {

      // the app offers no choice of limit type or outlier level. 'robust' would throw below in
      // the shared 'predict', which reads robust counts these results never carry
      const gamma = 1;
      const limType = 'classic';

      const Xcal = s.calsetp.values;
      const Xtar = s.tarsetp.values;
      const Xalt = isempty(s.altsetp) ? null : s.altsetp.values;
      const className = s.calsetp.classNames[0];

      // adjust number of components
      // here we take into account only variables as rows are taken in the global model
      const ncols = Xcal.ncols - s.varsExcluded.length;
      const ncompMax = s.model.ncomp > ncols ? ncols : s.model.ncomp;

      // the other route which reaches a result without passing 'handleOutliers': these results are
      // built from the low-level 'pca_predict', which never sees it. checked HERE and not inside
      // the 'then' so a damaged list rejects before a WASM module is built, which is work neither
      // caller wants done for a dataset that cannot produce a result. what that costs, stated
      // rather than hidden: a check here cannot see the array mutated in place while 'WASM()' is
      // awaited, which one inside the 'then' would - no path in this app mutates either of them -
      // and it captures these two lists while 'objlabels', 'classes' and 'classNames' are still
      // read live below, so reassigning 's.tarsetp' or 's.altres' mid-await would pair a captured
      // list with the new one's labels. it takes a field reassignment on THIS object to do that,
      // never a session replacement: 's' is this function's own parameter and both callers pass a
      // captured 'myS', so a replaced session never reaches this code at all. the pairing is also
      // not new - before this change all four were read live and were already skewed against the
      // 'Xtar' captured up here.
      //
      // 'checkedRowNumbers' returns the array it was given, so attaching these below changes no
      // identity. the alt list is read from 's.altres' while its values come from 's.altsetp': they
      // are the SAME array when preprocessing is skipped and the session has not been reloaded,
      // because this app has no outlier machinery at all and 'handleOutliers' therefore always
      // takes its identity-preserving branch, and otherwise separate arrays holding the same values
      // (a built twin is a clone, a reload parses each key on its own) - equal contents is the
      // guarantee. checking it against the row count of the block it is attached beside is what
      // makes a future divergence loud
      const tarRowNumbers = checkedRowNumbers(s.tarsetp.objindices, Xtar.nrows);
      const altRowNumbers = Xalt ? checkedRowNumbers(s.altres.objindices, Xalt.nrows) : null;

      return WASM()
         .then(Module => {
            // train PCA model with excluded variables
            const m = pca_fit(Module, Xcal, ncompMax, s.model.center, s.model.scale, [], s.varsExcluded);

            // get target class results
            const tarres = pca_predict(Module, m, Xtar);
            withoutResiduals(tarres);
            tarres['objindices'] = tarRowNumbers;
            tarres['objlabels'] = s.tarsetp.objlabels;
            tarres['classes'] = s.tarsetp.classes;
            tarres['classNames'] = s.tarsetp.classNames;
            tarres['cNh'] = pcamodel_get(m, "cNh");
            tarres['cNq'] = pcamodel_get(m, "cNq");

            // get alternative classes results
            let altres = {};
            if (Xalt) {
               altres = pca_predict(Module, m, Xalt);
               withoutResiduals(altres);
               altres['objindices'] = altRowNumbers;
               altres['objlabels'] = s.altres.objlabels;
               altres['classes'] = s.altres.classes;
               altres['classNames'] = s.altres.classNames;
               altres['cNh'] = pcamodel_get(m, "cNh");
               altres['cNq'] = pcamodel_get(m, "cNq");
            }

            // add additional properties to model object
            m['hash'] = genhash();
            m['varlabels'] = withoutExcluded(s.calsetp.varlabels, s.varsExcluded);
            m['varindices'] = withoutExcluded(s.calsetp.varindices, s.varsExcluded);
            m['varvalues'] = withoutExcluded(s.calsetp.varvalues, s.varsExcluded);
            m['varvaluesName'] = s.calsetp.varvaluesName;
            m['varvaluesUnits'] = s.calsetp.varvaluesUnits;
            m['varrev'] = s.calsetp.varrev
            m['header'] = s.calsetp.header
            m['prep'] = s.prepmodel;

            // compute probabilities for critical values
            const pe = 1 - s.alpha / 100;
            const poo = Math.pow(1 - gamma / 100, 1 / m.nrows);

            const lt = limType.charAt(0);
            const Nh = pcamodel_get(m, lt + 'Nh');
            const Nq = pcamodel_get(m, lt + 'Nq');
            const Nf = Nh.map((v, i) => v + Nq[i]);

            const eCrit = Nf.map(v => qchisq(pe, v));
            const oCrit = Nf.map(v => qchisq(poo, v));

            const simca = {
               ncomp: s.nComp,
               alpha: s.alpha,
               gamma,
               limType,
               Nf,
               eCrit,
               oCrit,
               className,
               hash: genhash()
            };


            // the alt branch is gated on the matrix: 'altres' starts as '{}', which is truthy,
            // and testing it built the branch in rigorous mode, where 'seq(0, undefined - 1)' threw
            return {
               model: m,
               simca: simca,
               tar: {
                  pca: tarres,
                  simca: predict(tarres, limType, eCrit, oCrit, {members: seq(0, tarres.nrows - 1), strangers: []})
               },
               alt: Xalt ? {
                  pca: altres,
                  simca: predict(altres, limType, eCrit, oCrit, {members: [], strangers: seq(0, altres.nrows - 1)})
               } : {}
            };

         });

   // no 'catch' here on purpose. this used to end with '.catch(e => console.error(e))', which
   // RESOLVED the promise with 'undefined' for every failure raised INSIDE the chain, which is
   // every one that matters here: both callers assign what comes back straight to 's.currentRes',
   // and by then they have already advanced 'varsExcluded' and 'intExcluded'. nothing between
   // those callers and 'pca_fit' guards its inputs, and that imported wrapper refuses fewer than
   // 3 rows or 2 columns while the column count here is the dataset width less the excluded
   // variables - so a refusal can reach this point, and the swallow turned it into an undefined
   // result. letting the rejection through is what lets each caller decide, and both now catch it
}


/**
 * Builds the comparison baseline the undo restores from a recomputed result.
 *
 * Without an alternative set 'res.alt' is '{}', and the specificity, selectivity and efficiency
 * are reported as zeros: 'getStat' reads those three baseline values only when an alternative
 * set is present, and its own results carry zeros for them otherwise.
 *
 * @param {Object} res - what 'getCurrentRes' resolved with.
 * @returns {Object} 'statsCurrent': 'ncompBest' and four Float64Arrays.
 */
export function getCurrentStats(res) {
   const sens = res.tar.simca.stat.sensitivity;
   const n = sens.length;
   const alt = isempty(res.alt) ? null : res.alt.simca.stat;
   const spec = alt ? alt.specificity : new Array(n).fill(0);
   const sel = alt ? alt.selectivity : new Array(n).fill(0);
   const eff = sens.map((v, i) => Math.sqrt(v * spec[i]));
   return {
      ncompBest: res.simca.ncomp,
      sens: new Float64Array(sens),
      spec: new Float64Array(spec),
      eff: new Float64Array(eff),
      sel: new Float64Array(sel),
   };
}


/**
 * The comparison baseline while nothing is excluded: the global statistics themselves, with
 * no best count yet. 'getCurrentStats' builds the same shape from a result.
 *
 * @param {Object} statsGlobal - the global statistics.
 * @returns {Object} 'statsCurrent': 'ncompBest' null and the four arrays, shared with the
 *    global ones.
 */
export function baselineFromGlobal(statsGlobal) {
   return {ncompBest: null, sens: statsGlobal.sens, spec: statsGlobal.spec, eff: statsGlobal.eff,
      sel: statsGlobal.sel};
}


/**
 * Computes theoretical selectivity of outcomes.
 *
 * @param {Float64Array} f - array with full distance values.
 * @param {Number} fCrit - critical value for extremes.
 * @param {Number} k - number of degrees of freedom (Nf)
 * @returns {Number} selectivity, or NaN if the distribution can not be fitted to these distances.
 *
 * Same fit as 'processStrangers' in '@mdatools-apps/shared/methods/simca.js' — keep the two in
 * step. The largest distances are trimmed away until the remaining ones are no more dispersed
 * than a noncentral chi-square with k DoF can be. When that state can not be reached, the fit
 * does not exist and NaN is returned rather than a number derived from Infinity.
 */
export function getSelectivity(f, fCrit, k) {

   let I = f.length;

   const fv = vector(f);
   let fp = fv.sort();

   // Step 2. If Disc <0
   let Disc = -1;
   let n = 0;
   let m = 0;
   let d = 0;
   let M1 = 0;

   // the fit needs a variance, and a variance needs at least two values
   if (I < 2) return NaN;

   while (Disc < 0) {
      if (n > 0) {
         // dropping another value would leave a single one, which has no variance. 'M1' can rise
         // rather than fall as the largest values go, because trimming moves the mean as well, so
         // this is reachable whenever a low lying object keeps the remainder too dispersed
         if (I < 3) return NaN;

         I = I - 1;
         fp = fp.slice(1, I);
      }
      m = mean(fp);
      // unbiased, dividing by (I - 1), as the method of moments in the source papers prescribes
      // and as the shared 'processStrangers' does. the biased form used here before made 'M1'
      // smaller by (I - 1)/I, so this app trimmed fewer samples and reported a different beta
      // than DD-SIMCA did for the very same distances
      d = variance(fp);
      M1 = d / (m * m);
      Disc = 4 - 2 * k * M1;
      n = n + 1;
   }

   // 'Disc >= 0' is the same condition as 's >= 0', but it does not cover M1 = 0, which passes as
   // Disc = 4 while meaning no dispersion at all — the limit s -> infinity, with no finite solution
   // on this branch. identical retained distances give exactly that, and all-zero ones give 0/0
   if (!(M1 > 0) || !Number.isFinite(M1) || !Number.isFinite(Disc) || !(m > 0) || !(k > 0)) {
      return NaN;
   }

   // Step 3. Solve the moment equations. writing x = k + s, the mean and variance of the scaled
   // distribution give M1*x^2 - 4x + 2k = 0, whose positive root is the one below
   const x = (2 + Math.sqrt(Disc)) / M1;

   // 	scaling factor and noncentrality
   const s = (x - k);
   const f0 = m / x;

   // Step 4. Sankaran's approximation to the noncentral chi-square distribution function
   const z = fCrit / f0;
   const h = 1 - 2 * (k + s) * (k + 3 * s) / (3 * (k + 2 * s)**2);
   const r = (h - 1) * (1 - 3 * h);
   const p = (k + 2 * s) / (k + s)**2;
   const Mz = 1 + h * p * (h - 1 - 0.5 * (2 - h) * r * p);
   const Sz = h * Math.sqrt(2 * p) * (1 + 0.5 * r * p);

   // Step 5. Given alpha, calculate beta
   const beta = pnorm((Math.pow(z / (k + s), h) - Mz) / Sz);

   if (![x, s, f0, h, Mz, Sz, beta].every(Number.isFinite) || !(f0 > 0) || !(Sz > 0)) {
      return NaN;
   }

   return 1 - beta;
}


/**
 * Returns JSON with sensitivity, specificity, efficiency and selectivity values
 * computed for current model and datasets. If statistics for best model are provided it also
 * computes the differences.
 *
 * @param {Object} m - JSON with PCA model.
 * @param {Object} rTarget - PCA results computed for target class (PV-set)
 * @param {Object} rAlt - PCA results computed for alternative classs (Alternative set)
 * @param {Object} statsCurrent - JSON with sensitivity, specificity, efficiency and selectivity of a current model.
 * @param {Number} alpha - the significance level.
 *
 * @returns {Object} JSON object for every statistic with two fields: 'val' with statistic value and
 * 'diff' difference between the value and the corresponding statistic from the current model. If the
 * current model statistics are not provided, 'diff' and 'val' are the same.
 */
export function getStat(m, rTarget, rAlt, statsCurrent, alpha = 5) {

   if (alpha < 0.01 || alpha > 50) {
      throw new Error("getStat: wrong value for 'alpha' parameter.");
   }

   let sensCurrent, specCurrent, effCurrent, selCurrent, ncompBest;

   if (!statsCurrent) {
      sensCurrent = new Float64Array(m.ncomp);
      specCurrent = new Float64Array(m.ncomp);
      effCurrent = new Float64Array(m.ncomp);
      selCurrent = new Float64Array(m.ncomp);
   } else {
      ncompBest = statsCurrent.ncompBest,
      sensCurrent = statsCurrent.sens;
      specCurrent = statsCurrent.spec;
      effCurrent = statsCurrent.eff;
      selCurrent = statsCurrent.sel;
   }

   const Nh = pcamodel_get(m, 'cNh');
   const h0 = pcamodel_get(m, 'ch0');
   const Nq = pcamodel_get(m, 'cNq');
   const q0 = pcamodel_get(m, 'cq0');

   const sens = new Float64Array(m.ncomp);
   const spec = new Float64Array(m.ncomp);
   const sel = new Float64Array(m.ncomp);
   const eff = new Float64Array(m.ncomp);

   const sensDiff = new Float64Array(m.ncomp);
   const specDiff = new Float64Array(m.ncomp);
   const selDiff = new Float64Array(m.ncomp);
   const effDiff = new Float64Array(m.ncomp);
   const palpha = 1 - alpha / 100;

   for (let a = 0; a < m.ncomp; a++) {
      const Nha = Nh[a]
      const h0a = h0[a];
      const Nqa = Nq[a]
      const q0a = q0[a];
      const Nfa = Nha + Nqa;
      const eCrit = qchisq(palpha, Nfa);
      let q, h;

      // get distances for target set results
      q = pcares_get(rTarget, 'qdist', a + 1);
      h = pcares_get(rTarget, 'hdist', a + 1);

      // compute sensitivity
      let sens_v = 0;
      for (let i = 0; i < rTarget.nrows; i++) {
         const f = h[i] / h0a * Nha + q[i] / q0a * Nqa;
         sens_v += (f < eCrit);
      }
      sens_v = sens_v / rTarget.nrows
      sens[a] = sens_v;

      // compute difference with current best sensitivity
      sensDiff[a] = sens[a] - sensCurrent[ncompBest ? (ncompBest - 1) : a];

      // get distances for alternative set results
      if (!isempty(rAlt)) {
         q = pcares_get(rAlt, 'qdist', a + 1);
         h = pcares_get(rAlt, 'hdist', a + 1);

         // compute specificity and selectivity
         const f_vec = Array(rAlt.nrows);
         let spec_v = 0;
         for (let i = 0; i < rAlt.nrows; i++) {
            const f = h[i] / h0a * Nha + q[i] / q0a * Nqa;
            spec_v += (f >= eCrit);
            f_vec[i] = f;
         }
         spec_v = spec_v / rAlt.nrows
         spec[a] = spec_v;
         sel[a] = getSelectivity(f_vec, eCrit, Nfa);

         // compute difference with current best values
         specDiff[a] = spec[a] - specCurrent[ncompBest ? (ncompBest - 1) : a];
         selDiff[a] = sel[a] - selCurrent[ncompBest ? (ncompBest - 1) : a];

         // compute efficiency and difference
         eff[a] = Math.sqrt(sens_v * spec_v);
         effDiff[a] = eff[a] - effCurrent[ncompBest ? (ncompBest - 1) : a];
      }
   }

   return {
      alpha: alpha,
      ncomp: m.ncomp,
      sens: {diff: sensDiff, val: sens},
      spec: {diff: specDiff, val: spec},
      sel: {diff: selDiff, val: sel},
      eff: {diff: effDiff, val: eff}
   };
}


/**
 * Create a PCA model, applies it to the PV-set and alternative set and compute main statistics.
 *
 * Takes an already built WASM module rather than the factory, because the caller runs this once
 * per interval - up to 50 times for a single selection run - and building a module per call cost
 * an instantiation each time without isolating anything: any failure ends the whole run regardless.
 *
 * @param {Object} Module - emscripten module.
 * @param {Object} props - varInd (excluded variables), nComp, Xcal, Xtar, Xalt, center, scale,
 *    statsCurrent and alpha.
 *
 * @returns {Object} JSON with outcomes, same as 'getStat'.
 * @throws whatever the fit, the predictions or 'getStat' throw; the caller ends its run on any
 *    of them.
 */
export async function getOutcomes(Module, props) {
   const { varInd, nComp, Xcal, Xtar, Xalt, center, scale, statsCurrent, alpha } = props;
   const m = pca_fit(Module, Xcal, nComp, center, scale, [], varInd);
   const tarres = pca_predict(Module, m, Xtar);
   const altres = Xalt ? pca_predict(Module, m, Xalt) : {};
   return getStat(m, tarres, altres, statsCurrent, alpha);
}


/**
 * Tells whether 'getVarselParams' would accept 'nInt' intervals for a dataset with 'nVars'
 * variables.
 *
 * It mirrors the refusals that method makes on its 'nInt' path. The width alone does not settle
 * the question, because the accepted range depends on the interval size derived from the count as
 * well: two intervals over 101 variables fit the width, yet give a size of 51 which the method
 * refuses. The sweep in 'test/test-utils.js' compares this against the method itself over a range
 * of widths and counts, so a change to either which disagrees inside that range goes red.
 *
 * @param {Number} nVars - total number of variables.
 * @param {Number} nInt - number of intervals.
 *
 * @returns {boolean} true if 'getVarselParams' accepts the count, false otherwise.
 */
export function acceptsNInt(nVars, nInt) {

   if (!Number.isInteger(nInt) || nInt < 2 || nInt > nVars) return false;

   // the interval size the method derives from the count. it can not come out below its lower
   // limit of 1 once the count is inside [2, nVars], so only the upper limit is tested here
   return Math.round(nVars / nInt) <= nVars / 2;
}


/**
 * Chooses the number of intervals a freshly mounted selection panel starts with.
 *
 * 'varselparams' arrives with the session, and it need not describe the dataset stored beside it:
 * the defect this guards against saved a new training set next to an older object, and neither
 * 'checkSession' nor the reset cascades compare the two. Its count may be reused only when the
 * object claims this exact width and the count is one 'getVarselParams' still accepts. Anything
 * else falls back to the count a fresh dataset of this width starts with.
 *
 * The width is the only evidence of provenance the object carries - everything else in it is
 * geometry derived from the variable values, which the caller recomputes anyway. So an object
 * left over from a DIFFERENT dataset of the SAME width passes here and its count survives. No
 * width based test anywhere can separate those two; it would take a fingerprint of the dataset,
 * stored alongside.
 *
 * @param {Object} varselparams - parameters carried by the session, or a falsy value if none.
 * @param {Number} nVars - number of variables in the dataset which is loaded now.
 *
 * @returns {Number} number of intervals to start from.
 */
export function getSeedNInt(varselparams, nVars) {

   const nIntDefault = nVars < 50 ? nVars : 10;

   if (!varselparams || varselparams.nVars !== nVars) return nIntDefault;

   return acceptsNInt(nVars, varselparams.nInt) ? varselparams.nInt : nIntDefault;
}


/**
 * Computes variable selection parameters based on total number of variables and interval size.
 * @param {Number} nVars - total number of variables.
 * @param {Number} nInt - number of intervals.
 * @param {Number} intSize - size of intervals (number of variables inside).
 * @param {Array} varValues - array with variable values.
 *
 * @returns {Object} JSON with interval parameters, including indices of left and right boundaries,
 * coordinates of left boundary shifted for making nice interval plots, etc.
 */
export function getVarselParams(nVars, nInt, intSize, varValues, varLabels) {

   if (!intSize && !nInt) {
      throw new Error('One of the two arguments "nInt" or "intSize" must be specified.');
   }

   if (nInt) {
      intSize = Math.round(nVars / nInt);
   } else {
      nInt = Math.round(nVars / intSize);
   }

   if (!Number.isInteger(nInt) || nInt < 2 || nInt > nVars) {
      throw new Error('Wrong value for "nInt" or "intSize" arguments.');
   }

   if (!Number.isInteger(intSize) || intSize < 1 || intSize > nVars / 2) {
      throw new Error('Wrong value for "nInt" or "intSize" arguments.');
   }

   // arrays with left and right indices of each interval
   const intLeftIndices = Array(nInt);
   const intRightIndices = Array(nInt);

   // arrays of bar properties to visualize the intervals on plots
   const mid = Array(nInt);
   const left = Array(nInt);
   const width = Array(nInt);

   // array for interval labels
   const intLabels = Array(nInt);

   // how many whole intervals can be fitted and what is the remainder
   const varRem = nVars % nInt;
   const nVarRem = Math.trunc(nVars / nInt);

   let i, leftInd, rightInd;

   // loop for computing indices of intervals
   if (nInt === nVars) {
      // one variable intervals
      intSize = 1;
      for (i = 0; i < nInt; i++) {
         intLeftIndices[i] = i;
         intRightIndices[i] = i;
         intLabels[i] = varLabels[i];
      }
   } else if (varRem === 0) {
      // all intervals of equal size
      for (i = 0; i < nInt; i++) {
         leftInd = i * nVarRem;
         intLeftIndices[i] = leftInd;
         intRightIndices[i] = leftInd + nVarRem - 1;
         intLabels[i] = varValues[intLeftIndices[i]] + '–' + varValues[intRightIndices[i]];
      }
   } else {
      // Loop for intervals with an extra element
      let currentInd = 0;

      // Loop for intervals with an extra element
      for (i = 0; i < varRem; i++) {
         intLeftIndices[i] = currentInd;
         currentInd += (nVarRem + 1);
         intRightIndices[i] = currentInd - 1;
         intLabels[i] = varValues[intLeftIndices[i]] + '—' + varValues[intRightIndices[i]];
      }

      // Loop for intervals with the minimum number of elements
      for (i = varRem; i < nInt; i++) {
         intLeftIndices[i] = currentInd;
         currentInd += nVarRem;
         intRightIndices[i] = currentInd - 1;
         intLabels[i] = varValues[intLeftIndices[i]] + '—' + varValues[intRightIndices[i]];
      }
   }

   let leftIndNext, rightIndPrev, leftVal, rightVal, leftValNext, rightValPrev, leftMargin, rightMargin;

   // loop to computer other parameters
   for (i = 0; i < nInt; i++) {

      // indices and values of current interval
      leftInd = intLeftIndices[i];                       // index of left boundary of i-th interval
      leftVal = varValues[leftInd];                      // value corresponding to left boundary

      rightInd = intRightIndices[i];                     // index of right boundary of i-th interval
      rightVal = varValues[rightInd]                     // value corresponding to right boundary


      // if this is not the first interval, compute left margin as half distance between this and previous interval
      if (i > 0) {
         rightIndPrev = intRightIndices[i - 1];
         rightValPrev = varValues[rightIndPrev];
         leftMargin = (leftVal - rightValPrev) / 2;
      }

      // if this is not the last interval, compute right margin as half distance between this and next interval
      if (i < nInt - 1) {
         leftIndNext = intLeftIndices[i + 1];
         leftValNext = varValues[leftIndNext];
         rightMargin = (leftValNext - rightVal) / 2;
      }

      // if this is the first interval use right margin as left
      if (i === 0) {
         leftMargin = rightMargin;
      }

      // if this is the last interval use left margin as right
      if (i === nInt - 1) {
         leftMargin = rightMargin;
      }

      // compute interval bar properties
      left[i] = leftVal - leftMargin;
      width[i] = rightVal - leftVal + leftMargin + rightMargin;
      mid[i] = (leftVal + rightVal) / 2;
   }

   return {
      nVars,
      nInt,
      intSize,
      intLeftIndices,
      intRightIndices,
      intLabels,
      left,
      width,
      mid
   };
}


/**
 * Finds best combination of number of intervals for given number of variables.
 *
 * @param {Number} nVars - number of variables in the dataset.
 *
 * @returns {Array} array with number of intervals options.
 */
export function getIntNumOptions(nVars) {

   // find exact match
   const v1 = [4, 6, 7, 8, 9].filter(v =>  v <= nVars && nVars % v === 0);

   // find other good options
   let v2;
   if (nVars >= 10 && nVars < 20) {
      v2 = [nVars];
   } else if (nVars >= 20 && nVars < 30) {
      v2 = [10, nVars];
   } else if (nVars >= 30 && nVars <= 50) {
      v2 = [10, 20, nVars];
   } else if (nVars > 50 && nVars < 70) {
      v2 = [10, 20, 30];
   } else if (nVars >= 70 && nVars < 90) {
      v2 = [10, 20, 30, 40];
   } else if (nVars >= 90) {
      v2 = [10, 20, 30, 40, 50];
   } else {
      // below 10 the count is the width itself, unless a divisor above already offers it: 2, 3
      // and 5 have none, and an empty list left the selector with nothing around its value
      v2 = v1.includes(nVars) ? [] : [nVars];
   }

   let v = [...v1, ...v2];
   return v.sort((a, b) => a - b);
}

/**
 * Number of components a selection run fits its candidates with.
 *
 * A candidate is fitted without the excluded variables and without one more interval, so the
 * narrowest one has 'nVars - excluded - widest' columns, 'widest' being the widest interval still
 * in. That interval can be one variable wider than the size derived from the count (a remainder
 * below half the count), and a run sized from that size made 'pca_fit' refuse the candidate
 * without it once the count reached the bound.
 *
 * @param {number} ncomp - the global model's component count.
 * @param {Object} varselparams - the partition.
 * @param {Array} intExcluded - indices of the excluded intervals.
 * @param {Array} varsExcluded - indices of the excluded variables.
 * @returns {number} the smaller of 'ncomp' and the narrowest candidate's column count.
 */
export function getRunNComp(ncomp, varselparams, intExcluded, varsExcluded) {
   let widest = 0;
   for (let i = 0; i < varselparams.nInt; i++) {
      if (intExcluded.includes(i)) continue;
      widest = Math.max(widest, varselparams.intRightIndices[i] - varselparams.intLeftIndices[i] + 1);
   }
   return Math.min(ncomp, varselparams.nVars - varsExcluded.length - widest);
}


/**
 * Computes limits for x-axis of the interval plots from the variable values of a dataset.
 *
 * @param {Object} calset - the calibration set, or null.
 * @returns {Array} [first, last] variable value, so reversed for descending values, with a margin
 *    of 10% before the first and 2.5% after the last.
 */
export function getLimX(calset) {
   if (!calset) return [0, 1];
   const mn = calset.varvalues[0];
   const mx = calset.varvalues[calset.varvalues.length - 1];
   const dx = mx - mn;
   return [mn - dx * 0.10, mx + dx * 0.025];
}


/**
 * Computes limits for y-axis of the outcomes plot in the difference view: the range of the
 * differences drawn, zero included, padded by a fifth of it on each side. When every difference
 * is zero the range is [-0.1, 0.1], as the axes need a span.
 *
 * @param {Object} outcomes - a finished run.
 * @param {Array} fomKeys - the figures of merit drawn.
 * @param {number} nComp - number of components whose column is drawn.
 * @param {number} nInt - number of intervals drawn: the partition's, which a stored run need
 *    not match; the column is read up to it, as the bars are.
 * @returns {Array} [min - pad, max + pad], or [-0.1, 0.1].
 */
export function getDiffLimY(outcomes, fomKeys, nComp, nInt) {
   let min = 0;
   let max = 0;
   for (const key of fomKeys) {
      const y = outcomes[key].diff.getcolumn(nComp).v;
      for (let i = 0; i < nInt; i++) {
         if (y[i] >= 0) max = Math.max(max, y[i]); else min = Math.min(min, y[i]);
      }
   }
   if (max === min) return [-0.1, 0.1];
   const pad = (max - min) * 0.2;
   return [min - pad, max + pad];
}


/**
 * Returns the rectangles which draw a partition's intervals on the interval plots. With descending
 * variable values the axis is reversed and the partition's widths are negative; its 'left' is
 * still the edge drawn on the left, so only the widths lose their sign.
 *
 * @param {Object} varselparams - the partition, or null.
 * @returns {Object|null} 'left' (the partition's own array), 'width', 'top' and 'height'.
 */
export function getIntervalSeries(varselparams) {
   if (!varselparams) return null;
   const n = varselparams.nInt;
   return {
      left: varselparams.left,
      width: varselparams.width.map(Math.abs),
      top: Array(n).fill(10),
      height: Array(n).fill(22),
   };
}


/**
 * Returns the bars which draw one statistic per interval on the outcomes plot: together they take
 * 84% of the interval's rectangle, centred on it, and statistic 'k' of 'nKeys' takes its share,
 * side by side in their order. A positive value is drawn up from zero, a negative one down from
 * zero.
 *
 * @param {Object} varselparams - the partition.
 * @param {Array|Float64Array} y - the statistic, read for each interval of the partition.
 * @param {number} k - which statistic the bars draw, from 0.
 * @param {number} nKeys - how many statistics share an interval.
 * @returns {Object} 'left', 'width', 'top' and 'height', one per interval.
 */
export function getBarSeries(varselparams, y, k, nKeys) {
   const l = varselparams.left;
   const w = varselparams.width;
   const n = w.length;
   const bw = 0.84 / nKeys;
   const left = Array(n);
   const width = Array(n);
   const top = Array(n);
   const height = Array(n);
   for (let i = 0; i < n; i++) {
      // from the edge drawn on the left: on a reversed axis 'w' is negative, and so are the steps
      left[i] = l[i] + (0.08 + k * bw) * w[i];
      width[i] = Math.abs(bw * w[i]);
      top[i] = y[i] >= 0 ? y[i] : 0;
      height[i] = Math.abs(y[i]);
   }
   return {left, width, top, height};
}


/**
 * Returns the rectangles of the excluded intervals, picked from the interval series.
 *
 * @param {Object|null} si - the series from 'getIntervalSeries'.
 * @param {Array} intExcluded - ids of the excluded intervals.
 * @returns {Object|null} the four arrays at the excluded ids, null without a series or an id.
 */
export function getExcludedSeries(si, intExcluded) {
   if (!si || intExcluded.length === 0) return null;
   const pick = (a) => intExcluded.map(i => a[i]);
   return {left: pick(si.left), width: pick(si.width), top: pick(si.top), height: pick(si.height)};
}


/**
 * Builds the CSV text of the progress table: a header, then one row per record with the
 * record's index, the excluded interval's number (a dash for the baseline), the component
 * count and the four statistics.
 *
 * @param {Array} statsProgress - the statistics of every step, the global baseline first.
 * @param {string} sep - value separator.
 * @param {string} dec - decimal separator; every '.' in the text is replaced by it.
 * @returns {string} the text.
 */
export function progressCSV(statsProgress, sep, dec) {
   let out = ['#', 'excluded interval', 'nPCs', 'sensitivity', 'specificity', 'efficiency',
      'selectivity'].join(sep) + '\n';
   for (let i = 0; i < statsProgress.length; i++) {
      const r = statsProgress[i];
      out += [i, i === 0 ? '-' : r.int, r.ncomp, r.sens, r.spec, r.eff, r.sel].join(sep) + '\n';
   }
   return dec === '.' ? out : out.replace(/\./g, dec);
}


// a figure of merit's name as a column heading
const fomHeading = (name) => name.charAt(0).toUpperCase() + name.slice(1);


/**
 * Builds the CSV of the data and intervals plot: one row per variable with its label, its value
 * on the x-axis, the mean and standard deviation of the training set, the interval it belongs to
 * (from 1) and whether it is excluded. The plot draws the mean and the deviation rescaled to its
 * own y-axis; these are the values.
 *
 * @param {Object} calset - the preprocessed training set the plot draws.
 * @param {Object|null} varselparams - the partition; without one the interval column is empty.
 * @param {Array} varsExcluded - indices of the excluded variables.
 * @param {string} xLabel - the x-axis label, heading the column of variable values.
 * @returns {string} the CSV text.
 */
export function intervalsCSV(calset, varselparams, varsExcluded, xLabel) {
   const { sep, dec } = calset;
   const n = calset.varvalues.length;
   const interval = Array(n).fill('');
   if (varselparams) {
      for (let k = 0; k < varselparams.nInt; k++) {
         for (let i = varselparams.intLeftIndices[k]; i <= varselparams.intRightIndices[k]; i++) {
            interval[i] = k + 1;
         }
      }
   }
   const excluded = new Set(varsExcluded);

   let out = csvRow(['Labels', xLabel, 'Mean', 'SD', 'Interval', 'Excluded'], sep, dec);
   for (let i = 0; i < n; i++) {
      const x = calset.values.getcolumn(i + 1);
      out += csvRow([calset.varlabels[i], calset.varvalues[i], mean(x), sd(x), interval[i],
         excluded.has(i) ? 'yes' : 'no'], sep, dec);
   }
   return out;
}


/**
 * Builds the CSV of the outcomes plot: one row per interval with its number (from 1), its first
 * and last variable values, whether it is excluded or selected, and the statistics drawn at
 * 'nComp' components - every one in the difference view, the chosen one otherwise. An excluded
 * interval was skipped by the run and gets no value. The value view adds the two horizontal
 * lines, 'global' and 'current', when the plot draws them.
 *
 * @param {Object} o - what the plot draws: 'calset', 'varselparams', 'intExcluded',
 * 'intSelected', 'outcomes' (a finished run), 'nComp', 'keys' (the statistics drawn), 'view'
 * ('diff' or 'val'), 'fomNames', and in the value view 'global' and 'current' (null when not
 * drawn).
 * @returns {string} the CSV text.
 */
export function outcomesCSV(o) {
   const { sep, dec } = o.calset;
   const vp = o.varselparams;
   const values = o.keys.map(k => o.outcomes[k][o.view].getcolumn(o.nComp).v);
   const head = o.keys.map(k => (o.view === 'diff' ? 'Difference in ' + o.fomNames[k] :
      fomHeading(o.fomNames[k])) + ' (A = ' + o.nComp + ')');

   let out = csvRow(['Interval', 'From', 'To', 'Excluded', 'Selected', ...head], sep, dec);
   for (let i = 0; i < vp.nInt; i++) {
      const excluded = o.intExcluded.includes(i);
      out += csvRow([i + 1, o.calset.varvalues[vp.intLeftIndices[i]],
         o.calset.varvalues[vp.intRightIndices[i]], excluded ? 'yes' : 'no',
         i === o.intSelected ? 'yes' : 'no', ...values.map(v => excluded ? '' : v[i])], sep, dec);
   }

   if (o.view !== 'diff') {
      for (const name of ['global', 'current']) {
         if (Number.isFinite(o[name])) out += csvRow([name, '', '', '', '', o[name]], sep, dec);
      }
   }
   return out;
}


/**
 * Builds the CSV of the statistics plot: one row per number of components and one column per
 * series drawn. A series shorter than the longest leaves its cells empty.
 *
 * @param {Array} series - the series drawn, each {name, values}.
 * @param {string} sep - value separator.
 * @param {string} dec - decimal separator.
 * @returns {string} the CSV text.
 */
export function statsCSV(series, sep, dec) {
   const n = Math.max(0, ...series.map(s => s.values.length));
   let out = csvRow(['PCs', ...series.map(s => s.name)], sep, dec);
   for (let a = 0; a < n; a++) {
      // past a series' end its value is undefined, which 'csvRow' writes as an empty field
      out += csvRow([a + 1, ...series.map(s => s.values[a])], sep, dec);
   }
   return out;
}


/**
 * Builds the CSV of the progress plot: one row per step with the interval excluded at it (a dash
 * for the global model at step 0) and every statistic drawn; then, when the plot shows the
 * selected interval as a candidate step, a row for it.
 *
 * @param {Array} statsProgress - the statistics of every step, the global model first.
 * @param {Array} keys - the statistics drawn.
 * @param {Object} fomNames - their names.
 * @param {Object|null} candidate - {id, values}: the selected interval's id (from 0) and its
 * statistic per key, or null.
 * @param {string} sep - value separator.
 * @param {string} dec - decimal separator.
 * @returns {string} the CSV text.
 */
export function progressPlotCSV(statsProgress, keys, fomNames, candidate, sep, dec) {
   const n = statsProgress.length;
   let out = csvRow(['Steps', 'Excluded interval', ...keys.map(k => fomHeading(fomNames[k]))],
      sep, dec);
   for (let i = 0; i < n; i++) {
      const r = statsProgress[i];
      out += csvRow([i, i === 0 ? '-' : r.int, ...keys.map(k => r[k])], sep, dec);
   }
   if (candidate) {
      out += csvRow([n, 'selected (' + (candidate.id + 1) + ')',
         ...keys.map(k => candidate.values[k])], sep, dec);
   }
   return out;
}
