<script>
   // local plot components and the plot router
   import PlotIntervals from './PlotIntervals.svelte';
   import PlotOutcomes from './PlotOutcomes.svelte';
   import PlotProgress from './PlotProgress.svelte';
   import PlotStats from './PlotStats.svelte';

   let {props, params, callbacks, selected } = $props();
   const s = $derived(props.s);
   const selectInt = $derived(props.selectInt);

   // the router keeps its own copy of the selection and renders Cancel and Exclude on it, the
   // plots and the table draw the session's. the first effect pushes a click up, the second
   // pushes the session's value down - every value, not only a cleared one as before, so that
   // a selection restored with the session gets its buttons without a second click. each write
   // of a value already held changes nothing, so the two settle after one run each. the
   // callback is read through a derived, as the session is: read off 'props' inside the
   // effect, it would repeat the push each time 'AppPlots' rebuilds 'props'
   $effect(() => {
      if (selected > -1) selectInt(selected);
   });

   $effect(() => {
      callbacks.select(s.intSelected);
   });

</script>

{#if params.plot === 'intervals' && s.outcomes && s.outcomes.status === 'done'}
<PlotOutcomes {props} {params} {callbacks} />
{:else if params.plot === 'progress' && s.statsProgress}
<PlotProgress {props} {params}  />
{:else if params.plot === 'statistics' }
<PlotStats {props} {params}  />
{:else}
<PlotIntervals {props} />
{/if}
