      if (bytes.byteLength !== len) return false;
      if (murmur128(bytes) !== String.fromCharCode(...lengthHash.subarray(4))) return false;
      const h = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
