<script>
   import { getContext } from 'svelte';
   import { checkCoords, transformCoords } from 'svelte-plots-basic/utils';
   import { PLOT_FONT_SIZE } from 'svelte-plots-basic/constants';

   let {
	   x,
      y,
      dx = 0,
      label,
      pos = 0,
      faceColor = '#404040',
      textSize = 1,                        // size of label symbols
   } = $props();

   function getAnchor(pos) {
      if (pos < 0.25) return 'start';
      if (pos > 0.75) return 'end';
      return 'middle';
   }

   function getX(pos) {
      if (pos < 0.25) return x;
      if (pos > 0.75) return x + dx;
      return x + dx/2;
   }

   // array with text anchors for correct positioning
   const textAnchor = $derived(getAnchor(pos));

   // get axes context and compute coordinates
   const axes = getContext('axes');
   const lineHeight = $derived(PLOT_FONT_SIZE[axes.scales().plot])

   // local status. a finite test, not truthiness: a coordinate of 0 is a position
   const isOk = $derived(Number.isFinite(x) && Number.isFinite(y));
   const xs = $derived(isOk ? transformCoords(checkCoords([getX(pos)]), axes.tX()) : null);
   const ys = $derived(isOk ? transformCoords(checkCoords([y]), axes.tY()) : null);
</script>

{#if isOk}
   {#each label as l, i}
   <text x={xs} y={ys - lineHeight * i} text-anchor={textAnchor} fill={faceColor} font-size='{textSize}em'>{l}</text>
   {/each}

{/if}
