<script>
   /***************************************************************/
   /* PlotIntervals                                               */
   /* --------------------                                        */
   /* shows intervals and illustrates selection process           */
   /***************************************************************/

   import { Rectangles, XAxis, YAxis, Box } from 'svelte-plots-basic/2d';
   import DatasetsPlotSeries from './DatasetsPlotSeries.svelte';
   import Axes from './Axes.svelte';
   import { getLimX, getIntervalSeries, getExcludedSeries, intervalsCSV } from './utils';
   import { downloadCSV, escapeText } from '@mdatools-apps/shared/utils';


   // inputs
   let {props } = $props();

   // file name for the plot
   const fileName = 'ddsimca-love-intervals';

   // get application state from properties
   const s = $derived(props.s)


   // reactive expressions for title, y-axis label and limits
   const title = $derived(s.outcomes && s.outcomes.status === 'running' ?
      'Calculation in progress...' : 'Data and intervals');

   const xLabel = $derived(s.calsetp.varAxisTitle);

   // series with intervals and with the excluded ones
   const si = $derived(getIntervalSeries(s.varselparams));
   const si_excl = $derived(getExcludedSeries(si, s.intExcluded));

   // series with currently processed interval. 'curInt' is -1 while the run is starting up and
   // has no interval yet, and indexing 'si' with that gives an undefined rectangle
   const pr = $derived(s.outcomes && s.outcomes.status === 'running' && s.outcomes.curInt >= 0 && si ? {
      left: [si.left[s.outcomes.curInt]],
      width: [si.width[s.outcomes.curInt]],
      top: [2],
      height: [4],
      faceColor: '#fffa0040' // yellowish
   } : null);

   // x-axis limits
   const limX = $derived(getLimX(s.calsetp));
   const limY = [0, 1.1];

   function downloadCSVCallback() {
      downloadCSV(intervalsCSV(s.calsetp, s.varselparams, s.varsExcluded, xLabel || 'Variables'),
         fileName);
   }
</script>


<Axes {fileName} {limX} {limY} {title} {downloadCSVCallback} >

   <DatasetsPlotSeries calset={s.calsetp} {limY} />

   {#if si_excl }
   <Rectangles
      lineColor="transparent"
      faceColor="#00000040"
      {...si_excl}
   />
   {/if}

   {#if pr}
   <Rectangles {...pr} />
   {/if}

   {#if si  }
   <Rectangles
      lineColor="#00000010"
      faceColor="#00000005"
      {...si}
   />
   {/if}

   <Box />
   <XAxis label={escapeText(xLabel)} />
   <YAxis showGrid={true} />
</Axes>