<script>
   /**************************************************************/
   /* AppPlots component for plots                               */
   /* -------------------------------                            */
   /* show main DD-SIMCA LOVE plot and enables interaction       */
   /* and excluding intervals.                                   */
   /**************************************************************/

   import { untrack } from 'svelte';
   import { isempty } from '@mdatools-apps/shared/utils';

   // local plot components and the plot router
   import PlotMain from './PlotMain.svelte';
   import PlotsRouter from '@mdatools-apps/shared/plots/PlotsRouter.svelte';

   // import control components
   import { Select, Range, getDefaults, Container, Button, Switch } from 'svelte-controls-basic'

   // inputs
   let {s, setExcluded, setNComp, selectInt, cancelSelection } = $props();

   // names for main figures of merits
   const fomNames = {
      'sens': 'sensitivity',
      'spec': 'specificity',
      'eff': 'efficiency',
      'sel': 'selectivity'
   };

   // the keys the plots draw. without an alternative set there are no strangers and the last
   // three statistics are zeros: the progress plot drew three flat series and the outcomes
   // plot three empty bars beside the one the control offers. 'params.main.fom' cannot
   // outlive the keys: in the app the list shrinks only when the set is nulled, which nulls
   // its result in the same flush and unmounts this component under the gate above it; a
   // session file carrying 'hasAlt' false beside a real set shrinks it too, and the loaded
   // session's new exclusion list remounts this component under its key, 'fom' at the default
   const fomKeys = $derived(isempty(s.altset) ? ['sens'] : Object.keys(fomNames));

   // colors for plot series
   const seriesColors = {
      'global': '#404040',
      'best': '#2679B2',
      'selected': '#D22C2F'
   }

   // the outcome the plots are drawn for
   const running = $derived(!!s.outcomes && s.outcomes.status === 'running');
   const done = $derived(!!s.outcomes && s.outcomes.status === 'done');
   const plotOptions = $derived(s.statsProgress ?
      ['intervals', 'progress', 'statistics'] : ['intervals', 'statistics']);

   // the plot controls, as Widget descriptors. 'hidden' carries what the session rules out and
   // 'hiddenWhen' what the selected plot rules out; Widget combines the two with OR and evaluates
   // the rule against the current selection. the object is derived from the session, so the
   // options and the slider's maximum follow it: the Range corrects an out of range value from
   // its own effect, and it mounts only once a run is done, over the maximum that run set
   const controls = $derived({
      main: {
         plot: {el: Select, name: 'plot', default: 'intervals', label: 'Show', hidden: running,
            props: {options: plotOptions}},
         fom: {el: Select, name: 'fom', default: 'sens', label: 'Statistic',
            props: {options: isempty(s.altset) ? ['sens'] : ['sens', 'spec', 'eff', 'sel']},
            hiddenWhen: (p) => p.plot === 'intervals' && !done},
         nComp: {el: Range, name: 'ncomp', default: 1, label: '# PCs', hidden: !done,
            props: {min: 1, max: done ? s.outcomes.ncomp : 1, step: 1, decNum: 0},
            hiddenWhen: (p) => p.plot === 'progress'},
         fomView: {el: Select, name: 'fomview', default: 'val', label: 'Show', hidden: !done,
            props: {options: ['diff', 'val']}, hiddenWhen: (p) => p.plot !== 'intervals'},
         zoom: {el: Switch, name: 'zoom', default: false, label: 'Zoom', hidden: running,
            props: {options: ['off', 'on']}, hiddenWhen: (p) => p.plot !== 'progress'},
      }
   });

   // JSON with plot components shown when new selection is made
   const plots = {
      main: {label: 'Outcomes', scope: 'objects', component: PlotMain, buttons: buttons},
   };

   // JSON with parameters for plots_active. the slider starts from the count the session holds -
   // a restored session carries one and an undo moves it - not from the control's default, which
   // used to overwrite the restored one at mount. untrack marks the reads at mount as deliberate;
   // the effect at the end follows later changes of the count
   let params = $state({
      main: {...getDefaults(untrack(() => controls.main)), nComp: untrack(() => s.nComp) || 1},
   });

   // a selection which has lost its plot: a run is drawn on the plot with the intervals, which
   // carries its marker, and the progress plot exists only once there is a progress
   $effect(() => {
      if (running || (!s.statsProgress && params.main.plot === 'progress')) {
         params.main.plot = 'intervals';
      }
   });

   // the session's count is the truth: the slider writes it, and the undo and the clamps in
   // 'AppContainer' write it back to the slider. an assignment of the value already held changes
   // nothing, so the two settle after one run each
   $effect(() => {
      setNComp(params.main.nComp);
   });
   $effect(() => {
      params.main.nComp = s.nComp;
   });


   // properties to send to plots
   const props = $derived({s, seriesColors, fomKeys, fomNames, selectInt});
</script>

{#snippet buttons()}
   {#if s.intSelected >= 0}
   <Container label="Selected ({s.intSelected + 1})">
      <Button onclick={cancelSelection} text="cancel" />
      <Button onclick={() => setExcluded()} text="exclude" class="destructive" />
   </Container>
   {/if}
{/snippet}


<PlotsRouter
   {props}
   {plots}
   {controls}
   selobjText = ''
   bind:params={params}
/>
