<script>
   /**************************************************************/
   /* --------------------                                       */
   /**************************************************************/

   import { Segments, TextLabels, Rectangles } from 'svelte-plots-basic/2d';
   import IntervalLabel from './IntervalLabel.svelte';
   import { getBarSeries } from './utils';

   let {s, limX, limY, fom, fomKeys, fomView, seriesColors} = $props();

   // coordinates of rectangles to show bar plots with statistics (and global value)
   const psAll = $derived.by(() => {

      if (!fomView || !s.outcomes || s.outcomes.status !== 'done') return null;

      // in the difference view the keys share the interval side by side; one key takes the
      // whole bar
      const diff = fomView === 'diff';
      let out = {};
      fomKeys.forEach((key, k) => {
         const y = s.outcomes[key][fomView].getcolumn(s.nComp).v;
         out[key] = {...getBarSeries(s.varselparams, y, diff ? k : 0, diff ? fomKeys.length : 1),
            faceColor: '#a8a04060'};
      });

      return out;
   });


   const psSelAll = $derived.by(() => {

      const is = s.intSelected;
      if (!psAll || is === undefined || is === null || is < 0) return null;

      const psl = {};
      const tsl = {};

      // coordinates of the interval label; 'IntervalLabel' places it at x, x + dx/2 or x + dx,
      // so its width keeps the partition's sign
      const ps1 = psAll[fomKeys[0]];
      const left = ps1.left[is]
      const width = Math.sign(s.varselparams.width[is]) * ps1.width[is]
      let intLeft, intWidth;
      if (fomView === 'diff' && fomKeys.length > 1) {
         intLeft = left - width/2;
         intWidth = width * fomKeys.length + width;
      } else {
         intLeft = left;
         intWidth = width;
      }

      for(const key of fomKeys) {
         const psk = psAll[key];

         const left = psk.left[is];
         const width = psk.width[is];
         const top = psk.top[is];
         const height = psk.height[is];
         const value = top === 0 ? -height : height;
         const label = s.varselparams.intLabels[is];

         psl[key] = {
            left:  [left],
            width: [width],
            top: [top],
            height: [height],
         }

         // in the difference view the label sits half a pad under the top edge: 'getDiffLimY'
         // pads the range by a fifth on each side, so half a pad is a fourteenth of the span
         tsl[key] = {
            x: intLeft,
            y: fomView === 'diff' ? limY[1] - (limY[1] - limY[0]) / 14 : 1.02,
            dx: intWidth,
            label: [value.toFixed(3), label],
            pos: is / s.varselparams.nInt,
            textSize: 0.80,
            faceColor: seriesColors.selected
         }
      }

      return {psl, tsl};
   });

   const globValue = $derived(s.statsGlobal && fom ?
      s.statsGlobal[fom][s.statsGlobal.ncompBest ? (s.statsGlobal.ncompBest - 1) : (s.nComp - 1)] : null);
   const bestValue = $derived(s.statsCurrent && fom && s.statsCurrent.ncompBest ?
      s.statsCurrent[fom][s.statsCurrent.ncompBest - 1] : null);

   const ps = $derived(psAll && fom ? psAll[fom] : null);
   const globXValue = $derived(ps ? (limX[0] + ps.left[0]) * 0.5 : 0);
</script>

{#if fomView === 'diff'}
   <!-- horizontal line at y = 0 -->
   <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[0]} yEnd={[0]} lineColor='#808080'/>

   <!-- bar plots with difference in statistics for all foms -->
   {#each fomKeys as key}
   <Rectangles {...psAll[key]}
      lineWidth={0}
      faceColor={'#a8a040' + (key === fom ? 'e0' : '60')}
   />
   {/each}

   {#if psSelAll}
      {#each fomKeys as key}
        <Rectangles {...psSelAll.psl[key]}
         lineWidth={0}
         faceColor={seriesColors.selected + (key === fom ? '' : '40')}
      />
      {/each}
      <IntervalLabel {...psSelAll.tsl[fom]} />
   {/if}
{:else}

   <!-- horizontal line at y = statistic for global model. a finite test: a statistic of 0 is
        drawn, a missing or NaN one is not -->
   {#if Number.isFinite(globValue)}
   <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[globValue]} yEnd={[globValue]}
      lineColor={seriesColors.global}/>
   <TextLabels xValues={[globXValue]} yValues={[globValue]} labels={[globValue.toFixed(3)]}
      pos={globValue > bestValue ? 3 : 1} textSize={0.85} faceColor={seriesColors.global}/>
   {/if}

   <!-- horizontal line at y = statistic for best model -->
   {#if Number.isFinite(bestValue)}
   <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[bestValue]} yEnd={[bestValue]} lineType={3}
      lineColor={seriesColors.best}/>
   <TextLabels xValues={[globXValue]} yValues={[bestValue]} labels={[bestValue.toFixed(3)]}
      pos={globValue > bestValue ? 1 : 3} textSize={0.85} faceColor={seriesColors.best}/>
   {/if}

   <!-- bar plot with statistics for selected fom -->
   <Rectangles {...ps} faceColor='#a8a04080' />

   {#if psSelAll}
      <Rectangles {...psSelAll.psl[fom]} lineWidth={0} faceColor={seriesColors.selected} />
      <IntervalLabel {...psSelAll.tsl[fom]} />
   {/if}

{/if}