import { checkedIntervalTrim, checkedIntervalId } from './checks.js';
import { seq } from '@mdatools-apps/shared/utils';


/**
 * Refuses an inconsistent stored exclusion state, writing exactly two fields.
 *
 * 'needsReset' is true because nothing stored says which side of the disagreement is authoritative,
 * so no run may be differenced against the baseline until 'resetExcluded' rebuilds it. That is the
 * flag 'failCurrentRes' already raises for a failed undo; only the comparison behind it is new.
 *
 * @param {Object} session - the 'train' part of the session.
 * @param {string} message - what the user is told.
 */
export function refuseExclusionState(session, message) {
   session.currentRes = null;
   session.outcomes = {status: 'error', message: message, needsReset: true};
}


/**
 * Performs the whole synchronous undo transition, or refuses having written nothing.
 *
 * The 'fewer than two exclusions' no-op lives here rather than in the handler so that it can carry
 * a test row. Everything the transition will read is checked BEFORE the first write, so a refusal
 * cannot leave the session half undone - which is the failure this guard exists to prevent and
 * would otherwise reintroduce.
 *
 * @param {Object} session - the 'train' part of the session.
 * @param {Object} varselparams - the partition, rebuilt from the live dataset.
 * @returns {boolean} true when the undo was performed, false when there was nothing to undo.
 * @throws {Error} when the stored state is unusable; nothing has been written.
 */
export function applyUndo(session, varselparams) {

   // corruption is not the same thing as having nothing to undo, so it is refused rather than
   // reported as a no-op. 'checkSession' already rejects such a session at load; this keeps the
   // function honest on its own terms
   if (!Array.isArray(session.intExcluded)) {
      throw new Error('applyUndo: the excluded interval list is not an array.');
   }

   // the first entry of 'statsProgress' is the global baseline, so there is nothing to undo back to
   if (session.intExcluded.length < 2) {
      return false;
   }

   const intLen = checkedIntervalTrim(session.intExcluded, session.varsExcluded, varselparams);

   // the undo ends by reading the component count of the entry the pop leaves last. Reading it
   // here, before anything moves, is what makes the transition all-or-nothing. One check covers
   // every progress list a STORED session can hold: 'JSON.parse' builds arrays with dense indices
   // from zero, so a list too short - or one holding a nullish entry - yields a value whose
   // 'ncomp' read throws, and an absent list throws on '.length', all before any write. A separate
   // length test and a separate '!previous' test were each tried and removed, because no test over
   // that domain could tell either from its own absence. Hand-built states outside it can: an
   // array carrying a '-1' own property answers the entry read with it
   const progress = session.statsProgress;
   const previous = progress[progress.length - 2];
   if (!Number.isFinite(previous.ncomp)) {
      throw new Error('applyUndo: the progress list has no usable entry to return to.');
   }

   // nothing above this line writes, and the first statement below it is the one which can still
   // fail: 'statsProgress' is not required to be an array, so an object carrying a 'length' can
   // satisfy the entry check above and have no 'pop'. That throws HERE, before any field of the
   // session has moved, which is the property that matters. Everything after it is an ordinary
   // array operation on a value already checked, with 'previous.ncomp' in hand. 'intSelected' is
   // written last so it cannot move ahead of the lists. The arrays are popped in place on purpose:
   // 'AppContainer' keys 'AppPlots' on the identity of 'intExcluded'
   progress.pop();
   session.intExcluded.pop();
   session.varsExcluded = session.varsExcluded.slice(0, session.varsExcluded.length - intLen);
   session.nComp = previous.ncomp;
   session.intSelected = -1;

   return true;
}


/**
 * Performs the whole synchronous exclusion transition, or refuses having written nothing.
 *
 * The inverse of 'applyUndo', kept beside it for the same reason: the refusals a restored
 * state can need carry test rows here. The four outcome rows - the reads of a stored value
 * nothing has vouched for - are read BEFORE the first write, so a stored outcome without the
 * matrices leaves the session as it was. The caller nulls 'outcomes' and 'currentRes'
 * afterwards, as 'undoExcluded' does.
 *
 * @param {Object} session - the 'train' part of the session.
 * @param {Object} varselparams - the partition, rebuilt from the live dataset.
 * @returns {boolean} true when the interval was excluded, false when there was nothing to do.
 * @throws {TypeError} when the stored outcome does not carry the matrices; nothing has been
 *    written.
 */
export function applyExclusion(session, varselparams) {

   // the rows below read the outcome directly, so a call made without a finished selection
   // cannot do its work. an effect in 'AppContainer' clears the selection which offers the
   // button, and this is the same refusal stated where it cannot be skipped: the handler is
   // reachable from a restored state
   const o = session.outcomes;
   if (!o || o.status !== 'done') return false;

   // the test is 'is this one of the intervals this partition has', not 'does it compare like
   // a number in range': a restored 'intSelected' can be null, a boolean, a fractional or a
   // numeric string, and all of them pass the comparisons. most read undefined from the bound
   // arrays; a canonical '2' indexes them correctly and then breaks 'id + 1' below, which
   // concatenates
   const id = session.intSelected;
   if (!checkedIntervalId(id, varselparams)) return false;

   // if it is already excluded do nothing
   if (session.intExcluded.includes(id)) return false;

   // the statistics of the interval to be excluded become the current model statistics, the
   // ones a run differences against. the outcome matrices hold one row per interval, one-based
   const n = session.nComp;
   const current = {
      ncompBest: n,
      sens: o.sens.val.getrow(id + 1).v,
      spec: o.spec.val.getrow(id + 1).v,
      eff: o.eff.val.getrow(id + 1).v,
      sel: o.sel.val.getrow(id + 1).v,
   };

   // if this is the first exclusion, save current ncomp as best to global statistics
   if (session.intExcluded.length === 0) {
      session.statsGlobal.ncompBest = n;
   }
   session.statsCurrent = current;

   // if progress statistics is empty create it and add global model statistics as first record
   if (!session.statsProgress) {
      const g = session.statsGlobal;
      session.statsProgress = [
         {ncomp: n, sens: g.sens[n - 1], spec: g.spec[n - 1], eff: g.eff[n - 1], sel: g.sel[n - 1]}
      ];
   }

   // and then add current statistics
   session.statsProgress.push({
      ncomp: n,
      int: id + 1,
      sens: current.sens[n - 1],
      spec: current.spec[n - 1],
      eff: current.eff[n - 1],
      sel: current.sel[n - 1],
   });

   // exclude the interval and extend the variable list. the interval list is pushed in place
   // on purpose: 'AppContainer' keys 'AppPlots' on its identity
   session.intExcluded.push(id);
   session.varsExcluded = session.varsExcluded.concat(
      seq(varselparams.intLeftIndices[id], varselparams.intRightIndices[id]));
   session.intSelected = -1;

   return true;
}
