<script>
   /***************************************************************/
   /* OutcomesPlot                                                */
   /* --------------------                                        */
   /* shows plot with intervals and statistics computed for       */
   /* interval models, also lets user to select and exclude       */
   /* a particular interval                                       */
   /***************************************************************/

   import { Rectangles, XAxis, YAxis, Box } from 'svelte-plots-basic/2d';
   import { getLimX, getDiffLimY, getIntervalSeries, getExcludedSeries, outcomesCSV } from './utils';
   import { downloadCSV, escapeText } from '@mdatools-apps/shared/utils';

   import DatasetsPlotSeries from './DatasetsPlotSeries.svelte';
   import OutcomesPlotSeries from './OutcomesPlotSeries.svelte';
   import Axes from './Axes.svelte';


   // inputs
   let {props, params, callbacks } = $props();

   // parameters for saving the plot
   const fileName = 'ddsimca-love-outcomes';

   const s = $derived(props.s);
   const fomKeys = $derived(props.fomKeys);
   const fomNames = $derived(props.fomNames);
   const seriesColors = $derived(props.seriesColors);

   const xLabel = $derived(s.calsetp.varAxisTitle);


   // reactive expressions for title, y-axis label and limits
   const title = $derived.by(() => {
      if (!s.outcomes) return 'Data and intervals';
      if (s.outcomes.status === 'running') return 'Selection in progress...';
      return 'Variable selection outcomes (A = ' + s.nComp + ')';
   });

   const yLabel = $derived.by(() => {
      if (!s.outcomes || s.outcomes.status === 'running') return ' ';
      return (params.fomView === 'diff' ? 'Difference in ' : '') + fomNames[params.fom];
   });


   // rectangles of the intervals and of the excluded ones
   const si = $derived(getIntervalSeries(s.varselparams));
   const si_excl = $derived(getExcludedSeries(si, s.intExcluded));

   // axis limits. in the difference view the y-axis follows the differences drawn; the test on
   // the run mirrors 'title': 'PlotMain' shows this plot for a finished run only
   const limX = $derived(getLimX(s.calsetp));
   const limY = $derived(params.fomView === 'diff' && s.outcomes?.status === 'done' ?
      getDiffLimY(s.outcomes, fomKeys, s.nComp, s.varselparams.nInt) : [0, 1.1]);

   // the rows as drawn: every statistic in the difference view, the chosen one with the global
   // and current lines otherwise. the two lines are read as 'OutcomesPlotSeries' reads them
   function downloadCSVCallback() {
      const diff = params.fomView === 'diff';
      const fom = params.fom;
      const g = s.statsGlobal, c = s.statsCurrent;
      downloadCSV(outcomesCSV({
         calset: s.calsetp, varselparams: s.varselparams, intExcluded: s.intExcluded,
         intSelected: s.intSelected, outcomes: s.outcomes, nComp: s.nComp,
         keys: diff ? fomKeys : [fom], view: diff ? 'diff' : 'val', fomNames,
         global: !diff && g ? g[fom][g.ncompBest ? g.ncompBest - 1 : s.nComp - 1] : null,
         current: !diff && c && c.ncompBest ? c[fom][c.ncompBest - 1] : null,
      }), fileName);
   }
</script>


<Axes {fileName} {limX} {limY} {title} {downloadCSVCallback} >

   <DatasetsPlotSeries calset={s.calsetp} {limY} />


   {#if s.outcomes}
      <OutcomesPlotSeries
         {s}
         {limX}
         {limY}
         {fomKeys}
         {seriesColors}
         fomView={params.fomView}
         fom={params.fom}
      />
   {/if}

   {#if si  && s.intSelected >= 0}
   <Rectangles
      left={[si.left[s.intSelected]]}
      width={[si.width[s.intSelected]]}
      top={[si.top[s.intSelected]]}
      height={[si.height[s.intSelected]]}
      lineColor="#00000010"
      faceColor="#ff000010"
   />
   {/if}

   {#if si }
   <Rectangles
      className="series-love-intervals"
      lineColor="#00000010"
      faceColor="#00000005"
      {...si}
      onclick={callbacks.select}
   />
   {/if}

   {#if si_excl }
   <Rectangles
      lineColor="transparent"
      faceColor="#00000040"
      {...si_excl}
   />
   {/if}

   <Box />
   <XAxis label={escapeText(xLabel)} />
   <YAxis label={yLabel} showGrid={true} />
</Axes>